import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Object3D, Color, DoubleSide } from 'three/webgpu';
import { texture, uniform, vec4, mix } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new Object3D();
  group.name = 'home-subhead';
  group.position.set(0, 1.85, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const cleanupFns = [];

  const imgUrl = '/prism-mock/home/nodes/cta-hero-isolated.png';
  const tex = ctx.textureLoader.load(imgUrl);
  tex.colorSpace = 'srgb';

  const w = 3.0;
  const h = (320 / 512) * w;
  const geometry = new PlaneGeometry(w, h);

  const material = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  const texNode = texture(tex);
  const grainAmount = uniform(0.02);
  material.colorNode = texNode;
  material.opacityNode = texNode.a;

  const planeMesh = new Mesh(geometry, material);
  planeMesh.name = 'home-subhead-plane';
  group.add(planeMesh);

  let textMesh = null;
  try {
    textMesh = createTextMesh({
      text: 'Atelier Noir — precise · luxury · technical',
      font: 'Lora',
      weight: 400,
      size: 0.20,
      color: new Color(config?.visual?.colors?.paper || '#e8ecf2'),
      fontAtlas: ctx.fontAtlas,
      maxWidth: w * 0.9,
      align: 'center',
    });
  } catch (e) {
    textMesh = null;
  }

  if (textMesh) {
    textMesh.name = 'home-subhead-text';
    textMesh.position.set(0, -h * 0.5 - 0.15, 0.01);
    group.add(textMesh);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    cleanupFns.forEach((fn) => {
      try { fn(); } catch (e) {}
    });
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  return group;
}
